func (s *Store) estimateFileSize(ss *segmentStack, footer *Footer) (int64, error) {
	var totalSize int64

	// Calculate size of all segments
	for _, segment := range ss.a {
		if segment.Len() <= 0 {
			continue
		}

		keyBytes, valBytes := segment.NumKeyValBytes()
		// Add some overhead for metadata (operation codes, lengths, etc.)
